// Builds generated/statutoryCalc.js, the server's copy of src/lib/statutoryCalc.ts (the payroll engine's PAYE, NSSF,
// SHIF and housing levy calculation), so the HR assistant's "what if" (ai_tools.js) gives the same figures as payroll.
// The server runs plain Node and cannot import TypeScript; statutoryCalc.ts imports nothing, so a plain transform is
// enough. tests/ai_tools.test.ts fails when the generated file is out of date: run `npm run build:server-lib`.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { transformSync } from "esbuild";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const SOURCE = resolve(root, "src/lib/statutoryCalc.ts");
export const OUTPUT = resolve(root, "generated/statutoryCalc.js");

const HEADER = `// GENERATED by scripts/build-server-lib.mjs from src/lib/statutoryCalc.ts. Do not edit: change the .ts file and run
// \`npm run build:server-lib\`. tests/ai_tools.test.ts fails when this file is out of date.
`;

/** The generated file's text for the current statutoryCalc.ts. */
export function buildStatutoryCalc() {
  const source = readFileSync(SOURCE, "utf8").replace(/\r\n/g, "\n");
  const { code } = transformSync(source, { loader: "ts", format: "esm", target: "node20" });
  return HEADER + code;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  mkdirSync(dirname(OUTPUT), { recursive: true });
  writeFileSync(OUTPUT, buildStatutoryCalc());
  console.log(`wrote ${OUTPUT}`);
}
